func TestIsPkgCvesDetactable(t *testing.T) {
	base := models.ScanResult{Family: constant.Debian, Release: "10", Packages: models.Packages{"apt": {Name: "apt"}}}
	cases := []struct {
		name   string
		change func(*models.ScanResult)
		want   bool
	}{
		{"supported OS", func(*models.ScanResult) {}, true},
		{"missing family", func(r *models.ScanResult) { r.Family = "" }, false},
		{"missing release", func(r *models.ScanResult) { r.Release = "" }, false},
		{"no packages", func(r *models.ScanResult) { r.Packages = nil }, false},
		{"Trivy", func(r *models.ScanResult) { r.ScannedBy = "trivy" }, false},
		{"FreeBSD", func(r *models.ScanResult) { r.Family = constant.FreeBSD }, false},
		{"Raspbian", func(r *models.ScanResult) { r.Family = constant.Raspbian }, false},
		{"pseudo", func(r *models.ScanResult) { r.Family = constant.ServerTypePseudo }, false},
		{"source packages only", func(r *models.ScanResult) { r.Packages = nil; r.SrcPackages = models.SrcPackages{"apt": {Name: "apt"}} }, true},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			r := base
			tc.change(&r)
			if got := isPkgCvesDetactable(&r); got != tc.want {
				t.Errorf("isPkgCvesDetactable() = %v, want %v", got, tc.want)
			}
		})
	}
}

func TestReuseScannedCvesTrivy(t *testing.T) {
	r := models.ScanResult{Family: constant.Debian, ScannedBy: "trivy"}
	if !reuseScannedCves(&r) {
		t.Fatal("Trivy CVEs should be reused without Optional metadata")
	}
	r.ScannedBy = ""
	r.Optional = map[string]interface{}{"trivy-target": "legacy"}
	if reuseScannedCves(&r) {
		t.Fatal("Optional metadata must not identify a Trivy scan")
	}
}

